insert into public.products
  (id, name, short_name, category, badge, price, compare_at, tagline, description, contents, how_to, details, variants, media, cta, active, sort_order)
values
  ('grow-tin', 'The Windowsill Grow Tin', 'Grow Tin', 'grow-tins', 'Bestseller for Workspaces', 199, 249, 'A desk-sized herb studio. Everything you need, in one seamless tin.', 'One matte alloy tin holds the whole ritual: three compressed Muthur coir coins, a packet of seeds and a handcrafted wooden marker. Add a splash of water, sow, and set it on a bright sill. No soil bag, no tray, no mess.', array['1× Seamless Alloy Grow Tin', '3× 50mm Muthur Low-EC Coir Coins', '1× Seed Packet', '1× Handcrafted Wooden Marker'], array['Place 1 dry coin in the tin and pour 5 tablespoons of tap water.', 'Wait about 60 seconds while it expands 7× into airy substrate.', 'Sprinkle 3–4 seeds, cover gently, and keep under indirect light.', 'Sprouts appear in 4–6 days. Mist lightly when the surface feels dry.'], array['Matte, rust-resistant alloy tin with lid, reusable for every sowing', 'Each coin expands 7× to fill the tin', 'Germination guaranteed or we reship free'], array['Sweet Italian Basil', 'English Thyme', 'Cherry Tomato', 'Native Coriander'], '[{"kind":"photo","name":"grow-tin"}]'::jsonb, 'Add to Cart', true, 10),
  ('living-soil-kit', 'Expand-In-The-Bag Living Soil Kit (650g)', 'Living Soil Kit', 'soil', 'Zero-Bucket Indoor Potting', 299, null, 'Makes 10 litres of soil. No tub, no bucket, no mess.', 'A compressed block of triple-washed Low-EC coir in a heavy waterproof kraft pouch. Pour water straight into the bag, wait, fluff, and stir in the bio-booster. Ten litres of airy living soil, made on your kitchen counter.', array['Heavy-duty 150-micron waterproof kraft gusset pouch', 'Pour 3.5L water directly into the bag', '100g dry vermicompost sachet', 'Cold-pressed neem cake sachet'], array['Unzip the pouch and pour 3.5L of water to the fill line.', 'Wait about 20 minutes for the block to expand.', 'Fluff by hand inside the bag, then tip in the bio-booster sachets.', 'Use straight from the pouch for repotting or fresh sowing.'], array['Ideal for repotting monsteras, pothos and balcony herbs'], array['650g • Makes 10L'], '[{"kind":"photo","name":"coco-peat-pouch"},{"kind":"photo","name":"expand-in-bag"}]'::jsonb, 'Add to Cart', true, 20),
  ('kitchen-trio', 'The Kitchen Trio Herb Garden', 'Kitchen Trio', 'gifts', 'Most Popular Gift • Save 20%', 499, 599, 'Three tins for the kitchen sill, ready to give.', 'Basil, cherry tomato and mint, each in its own Grow Tin with three coir coins, sleeved together in embossed unbleached kraft. A considered gift that keeps growing long after it is unwrapped.', array['3× Grow Tins: Basil, Cherry Tomato & Mint', '9× Low-EC Coir Coins (3 per tin)', 'Custom embossed unbleached kraft gift sleeve'], array['Hydrate one coin per tin with 5 tablespoons of water.', 'Sow each tin with its own seed packet and label it with the marker.', 'Keep the trio together on a bright kitchen sill.'], array['Gift-ready: arrives sleeved, no extra wrapping needed', 'Corporate and wholesale gifting available on request'], array['Basil + Cherry Tomato + Mint'], '[{"kind":"photo","name":"kitchen-trio","fit":"contain"}]'::jsonb, 'Claim Trio Kit', true, 30),
  ('coin-refill', '3-Coin Refill Pack', 'Coin Refill', 'refills', 'Refill', 49, null, 'Three extra 50mm Low-EC coins for your next sowing.', 'Three compressed Muthur coir coins, sized for the Grow Tin. Keep a pack in the drawer for the next round of herbs.', array['3× 50mm Muthur Low-EC Coir Coins'], array['Hydrate one coin with 5 tablespoons of water, then sow as usual.'], '{}'::text[], array['3× 50mm coins'], '[{"kind":"photo","name":"coin-refill"}]'::jsonb, 'Add to Cart', true, 40)
